  "key_assumptions": [
    {
      "assumption": "Data used for training AI inherently encodes historical and social power imbalances that cannot be 'scrubbed' away.",
      "if_wrong": "If technical methods could truly sanitize data of all bias, my critique of the neutrality myth would lose its primary empirical basis."
    }
  ]
}

